/* ---- Mercy rule (resignation) panel ---------------------------------- */
/* The verdict banner is the whole point of the card: one glance should say
   whether resignation is paying for itself. Colour carries the verdict, but
   never alone — the headline text states it too. */
.resign-card { margin-top: 1rem; }

.resign-verdict {
    display: flex;
    align-items: flex-start;
    gap: 0.7rem;
    padding: 0.75rem 0.9rem;
    margin-bottom: 0.9rem;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(255, 255, 255, 0.03);
}

.resign-verdict-dot {
    width: 9px;
    height: 9px;
    margin-top: 0.35rem;
    border-radius: 50%;
    flex: 0 0 auto;
    background: var(--text-dim, #9a9a9a);
}

.resign-verdict-text { display: flex; flex-direction: column; gap: 0.15rem; }
.resign-verdict-text strong { font-size: 0.92rem; }
.resign-verdict-text small { color: var(--text-dim, #9a9a9a); line-height: 1.45; }

.resign-verdict.is-good {
    border-color: rgba(76, 175, 80, 0.35);
    background: rgba(76, 175, 80, 0.08);
}
.resign-verdict.is-good .resign-verdict-dot { background: var(--success); box-shadow: 0 0 8px var(--success); }
.resign-verdict.is-good strong { color: var(--success); }

.resign-verdict.is-caution,
.resign-verdict.is-unproven {
    border-color: rgba(255, 167, 38, 0.35);
    background: rgba(255, 167, 38, 0.07);
}
.resign-verdict.is-caution .resign-verdict-dot,
.resign-verdict.is-unproven .resign-verdict-dot { background: var(--warning); }
.resign-verdict.is-caution strong,
.resign-verdict.is-unproven strong { color: var(--warning); }

.resign-verdict.is-bad {
    border-color: rgba(239, 83, 80, 0.4);
    background: rgba(239, 83, 80, 0.09);
}
.resign-verdict.is-bad .resign-verdict-dot { background: var(--danger); box-shadow: 0 0 8px var(--danger); }
.resign-verdict.is-bad strong { color: var(--danger); }

.resign-stats { margin-bottom: 0.9rem; }
