(() => {
  // Drive the real render path with a synthetic payload (no data is written).
  const card = document.getElementById('resign-card');
  card.hidden = false;
  const pts = [];
  let checked = 0, wrong = 0;
  for (let i = 1; i <= 14; i++) {
    checked += 1;
    if (i === 4 || i === 9) wrong += 1;
    const p = wrong / checked;
    const z = 1.96, d = 1 + z*z/checked;
    const c = (p + z*z/(2*checked)) / d;
    const m = z*Math.sqrt(p*(1-p)/checked + z*z/(4*checked*checked)) / d;
    pts.push({iteration: i, games: 8, resigned: Math.min(8, i),
              resign_rate: Math.min(1, i/10), checked: 1,
              cum_checked: checked, cum_false_rate: p,
              cum_ci_low: Math.max(0, c-m), cum_ci_high: Math.min(1, c+m)});
  }
  updateResignChart(pts, 0.05);
  const ds = resignChart.data.datasets;
  return {
    bars: ds[0].data.length, line: ds[1].data.length,
    band_high: ds[2].data.length, band_low: ds[3].data.length,
    danger_line: resignChart.$dangerRate,
    canvas_painted: document.getElementById('resign-chart').toDataURL().length > 5000,
    y1_max: resignChart.scales.y1.max,
  };
})()

