input.text:
(() => {
  // Render each verdict state through the real banner code path.
  const states = [
    ['good', 'Safe and saving time (2% wrong)', 'Across 120 checks the wrong-resignation rate is below the 5% danger line even at the top of its confidence interval.'],
    ['caution', 'Looks safe so far (0% wrong)', 'Consistent with a safe threshold, but with 15 checks the true rate could still be as high as 20%. Keep collecting before trusting it.'],
    ['unproven', 'Saving time — not yet proven safe (3/10 checks)', '48 games ended early, but only 3 playout checks have been collected so far.'],
    ['bad', '25% of resignations were wrong', '4 of 16 checked games were won by the side the rule called hopeless. Raise Resign Confidence or Confirming Moves.'],
  ];
  const out = [];
  for (const [v, head, detail] of states) {
    const b = document.getElementById('resign-verdict');
    b.className = `resign-verdict is-${v}`;
    document.getElementById('resign-headline').textContent = head;
    document.getElementById('resign-detail').textContent = detail;
    const cs = getComputedStyle(document.querySelector('.resign-verdict-dot'));
    out.push({verdict: v, dot: cs.backgroundColor,
              headline_color: getComputedStyle(document.getElementById('resign-headline')).color});
  }
  return out;
})()

